<template>
  <div :style="computedStyle">
    <slot />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export default defineComponent({
  name: 'Padding',
  props: {
    height: {
      type: String,
      required: true
    }
  },
  computed: {
    computedStyle(): Record<string, string> {
      return {
        'min-height': this.height
      };
    }
  }
});
</script>

